schema_ddl:
CREATE TABLE conti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_conto TEXT NOT NULL UNIQUE,
    giacenza NUMERIC(15,2) NOT NULL DEFAULT 0 CHECK (giacenza >= 0),
    data_apertura DATE NOT NULL
);

CREATE TABLE movimenti_contabili (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_anagrafico INT NOT NULL,
    importo NUMERIC(15,2) NOT NULL CHECK (importo != 0),
    data_operazione TIMESTAMP NOT NULL,
    tipo_operazione TEXT NOT NULL CHECK (tipo_operazione IN ('addebitamento', 'accredito', 'bonifico'))
);

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE categorie_movimenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_categoria TEXT NOT NULL UNIQUE,
    descrizione TEXT
);

CREATE TABLE dettagli_movimenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movimento_id INT NOT NULL,
    categoria_id INT NOT NULL,
    descrizione_dettaglio TEXT,
    importo_dettaglio NUMERIC(15,2) NOT NULL CHECK (importo_dettaglio > 0)
);
